function durum(program) {
  const simdi = new Date();
  const gun = (simdi.getDay() + 6) % 7; // Pazartesi=0
  const dakika = simdi.getHours()*60 + simdi.getMinutes();
  const bugun = program[gun] || [];
  for (const [b, s] of bugun) if (dakika >= b && dakika < s) return {acik:true, kapanis:s};
  // find next opening
  for (let i = 0; i < 7; i++) {
     const g = (gun + i) % 7;
