+            let bas = gun_indeksi(bas)?;
+            let son = gun_indeksi(son)?;
+            let mut gun = bas;
+            loop {
+                gunler.push(gun);
+                if gun == son || gunler.len() > 7 {
+                    break;
+                }
+                gun = (gun + 1) % 7;
+            }
+        } else {
+            gunler.push(gun_indeksi(parca)?);
+        }
+    }
+    if gunler.is_empty() || gunler.len() > 7 {
+        None
+    } else {
+        Some(gunler)
+    }
