impl LeadApp {
    fn sektor_paneli(&mut self, ctx: &egui::Context) {
        if !self.sektor_panel_acik { return; }
        let ekran = ctx.screen_rect();
        let boyut = egui::vec2((ekran.width() - 120.0).min(880.0), (ekran.height() - 140.0).min(600.0));
        let konum = ekran.center() - boyut * 0.5;
        let mut kapat = false;

        // Arka planı karart; dışına tıklama paneli kapatır.
        egui::Area::new(egui::Id::new("sektor_panel_ortu"))
            .order(egui::Order::Middle)
            .fixed_pos(ekran.min)
            .show(ctx, |ui| {
                let (rect, yanit) = ui.allocate_exact_size(ekran.size(), egui::Sense::click());
                ui.painter().rect_filled(rect, 0.0, egui::Color32::from_black_alpha(160));
                if yanit.clicked() { kapat = true; }
                if yanit.hovered() { ui.ctx().set_cursor_icon(egui::CursorIcon::Default); }
            });

        egui::Area::new(egui::Id::new("sektor_panel"))
            .order(egui::Order::Foreground)
            .fixed_pos(konum)
            .show(ctx, |ui| {
                egui::Frame::none()
                    .fill(KART)
                    .stroke(egui::Stroke::new(1.0_f32, KENAR_GUCLU))
                    .rounding(egui::Rounding::same(16.0))
                    .inner_margin(egui::Margin::symmetric(22.0, 18.0))
                    .shadow(...)  // optional
                    .show(ui, |ui| {
                        ui.set_width(boyut.x - 44.0);
                        ui.set_height(boyut.y - 36.0);
                        self.sektor_paneli_icerik(ui, &mut kapat);
                    });
            });

        if kapat || ctx.input(|girdi| girdi.key_pressed(egui::Key::Escape)) {
            self.sektor_panel_acik = false;
        }
    }
}
```

