        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    yanit
}

/// Paneldeki grup satırı: ad, sektör sayısı, seçili vurgusu.
fn grup_satiri(ui: &mut egui::Ui, ad: &str, sayi: usize, aktif: bool) -> egui::Response {
    let genislik = ui.available_width();
    let (rect, yanit) = ui.allocate_exact_size(egui::vec2(genislik, 25.0), egui::Sense::click());
    let t = ui.ctx().animate_bool_with_time(yanit.id, yanit.hovered(), 0.10);
    if aktif {
        ui.painter().rect_filled(rect, egui::Rounding::same(7.0), VURGU.gamma_multiply(0.14));
    } else if t > 0.0 {
        ui.painter().rect_filled(rect, egui::Rounding::same(7.0), KENAR.gamma_multiply(t));
    }
    ui.painter().text(
        rect.left_center() + egui::vec2(9.0, 0.0),
        egui::Align2::LEFT_CENTER,
        ad,
        govde_font(11.0),
        if aktif { VURGU } else if yanit.hovered() { METIN } else { SOLUK },
    );
    ui.painter().text(
        rect.right_center() - egui::vec2(9.0, 0.0),
        egui::Align2::RIGHT_CENTER,
        sayi.to_string(),
        govde_font(9.5),
        DIM,
    );
    yanit
}

