    let genislik = ui.available_width();
    let (rect, yanit) = ui.allocate_exact_size(egui::vec2(genislik, 24.0), egui::Sense::click());
    let t = ui.ctx().animate_bool_with_time(yanit.id, yanit.hovered(), 0.10);
    if secili {
        ui.painter().rect_filled(rect, egui::Rounding::same(7.0), VURGU.gamma_multiply(0.13));
        let cubuk = egui::Rect::from_min_size(rect.left_top() + egui::vec2(2.0, 6.0), egui::vec2(3.0, 12.0));
        ui.painter().rect_filled(cubuk, egui::Rounding::same(2.0), VURGU);
    } else if t > 0.0 {
        ui.painter().rect_filled(rect, egui::Rounding::same(7.0), KENAR.gamma_multiply(t * 0.8));
    }
    ui.painter().text(
        rect.left_center() + egui::vec2(13.0, 0.0),
        egui::Align2::LEFT_CENTER,
        ad,
        govde_font(12.0),
        if secili { VURGU } else if yanit.hovered() { METIN } else { SOLUK },
    );
    if !alt.is_empty() {
        ui.painter().text(
            rect.right_center() - egui::vec2(10.0, 0.0),
            egui::Align2::RIGHT_CENTER,
            alt,
            govde_font(9.5),
            DIM,
        );
    }
    if yanit.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    yanit
}
