+/// Arama sonuçlarını lead kalitesine göre sıralar: puanı yüksek olan önce,
+/// eşitlikte alfabetik sıra (Türkçe karakterler sadeleştirilerek). Sorgu
+/// başına 20 kayıt sınırı olduğu için listeye hangi kayıtların girdiği de bu
+/// sıralamaya bağlıdır; il geneli taramada ilçe başına ayrılan kota da
+/// böylece ilçenin en iyi kayıtlarından doldurulur.
+fn leads_sirala(liste: &mut [BusinessLead]) {
+    liste.sort_by(|a, b| {
+        kalite_puani(b)
+            .cmp(&kalite_puani(a))
+            .then_with(|| arama_anahtari(&a.name).cmp(&arama_anahtari(&b.name)))
+    });
+}
