/// Yüksek potansiyel eşiği: bu puanın üstündeki işletmeler arayüzde
/// "yüksek potansiyel" olarak işaretlenir.
const YUKSEK_POTANSIYEL: u8 = 70;

/// İşletmenin satın alma potansiyeli (0-100). Yalnızca tarama sırasında
/// elimizde olan veriler kullanılır; ek ağ isteği yapılmaz.
///
///   telefon (WhatsApp'tan ulaşılabilir)  +35
///   çalışma saatleri (aktif işletme)     +15
///   kapı numaralı adres                  +15   (sokak/mahalle bilgisi: +10)
///   koordinat                            +5
///   sektörün web ihtiyacı                +5..20
///   Google kaydı (doğrulanmış işletme)   +10
fn potansiyel_puani(isletme: &BusinessLead) -> u8 {
    let mut puan = 0u8;
    if whatsapp_numarasi(&isletme.phone).is_some() {
        puan += 35;
    }
    if !isletme.calisma_saatleri.trim().is_empty() {
        puan += 15;
    }
    if isletme.address.contains("No:") {
        puan += 15;
    } else if isletme.address.contains(',') {
        puan += 10;
    }
    if isletme.konum.is_some() {
        puan += 5;
    }
    puan += sektor_potansiyeli(&isletme.category);
    if isletme.kaynak.contains("google.com") {
        puan += 10;
    }
    puan.min(100)
}

/// Puanın nereden geldiğini tek satırda yazar: "82/100 · telefon · çalışma
/// saatleri · sokak adresi · yüksek sektör ihtiyacı". Arayüzde gerekçe
/// olarak gösterilir, böylece sıralama şeffaf kalır.
fn potansiyel_gerekcesi(isletme: &BusinessLead) -> String {
    let mut parcalar: Vec<&str> = Vec::new();
    if whatsapp_numarasi(&isletme.phone).is_some() {
        parcalar.push("telefon");
    }
    if !isletme.calisma_saatleri.trim().is_empty() {
        parcalar.push("çalışma saatleri");
    }
    if isletme.address.contains("No:") {
        parcalar.push("kapı numaralı adres");
    } else if isletme.address.contains(',') {
        parcalar.push("sokak/mahalle");
    }
    if isletme.konum.is_some() {
        parcalar.push("konum");
    }
    match sektor_potansiyeli(&isletme.category) {
        20 => parcalar.push("sektör ihtiyacı yüksek"),
        15 => parcalar.push("sektör ihtiyacı orta"),
        _ => {}
    }
    if isletme.kaynak.contains("google.com") {
        parcalar.push("Google kaydı");
    }
    if parcalar.is_empty() {
        parcalar.push("yalnızca isim");
    }
    format!("{}/100 · {}", potansiyel_puani(isletme), parcalar.join(" · "))
}

/// Arama sonuçlarını satın alma potansiyeline göre sıralar: puanı yüksek
