const ISTEK_DENEMESI: usize = 3;

/// Geçici sayılan hatalar: sunucu yoğunluğu (429), sunucu hatası (5xx) ve ağ
/// kesintisi. Bunlarda istek tekrar denenir; kalıcı hatalarda (404, 400...)
/// hemen dönülür.
fn gecici_hata(mesaj: &str) -> bool {
    mesaj.contains("HTTP 429")
        || mesaj.contains("HTTP 5")
        || mesaj.contains("bağlantı kurulamadı")
        || mesaj.contains("bağlantı kesildi")
}

/// İsteği artan bekleme süresiyle tekrar dener (0,8 → 1,6 → 3,2 sn).
fn tekrar_dene<T>(mut islem: impl FnMut() -> Result<T, String>) -> Result<T, String> {
    let mut bekleme = Duration::from_millis(800);
    let mut son_hata = String::new();
    for deneme in 1..=ISTEK_DENEMESI {
        match islem() {
            Ok(deger) => return Ok(deger),
            Err(hata) => {
                let tekrar = gecici_hata(&hata) && deneme < ISTEK_DENEMESI;
                son_hata = hata;
                if !tekrar {
                    break;
                }
                thread::sleep(bekleme);
                bekleme *= 2;
            }
        }
    }
    Err(son_hata)
}

