enum IlceTaramasi {
    Onbellek(SonucOnbellekKaydi),
    Ag {
        leads: Vec<BusinessLead>,
        siteli: usize,
        sunucu: &'static str,
    },
    Hata(String),
}

impl IlceTaramasi {
    fn hata(&self) -> Option<&str> {
        match self {
            IlceTaramasi::Hata(hata) => Some(hata),
            _ => None,
        }
    }

    /// `(liste, siteli, sunucu, önbellek_gunu)`; önbellek günü `None` ise sonuç
