            IlceTaramasi::Ag {
                leads,
                siteli,
                sunucu,
            } => Ok((leads, siteli, sunucu, None)),
            IlceTaramasi::Hata(hata) => Err(hata),
        }
    }
}

/// Bir ilçeyi tarar: önce sonuç önbelleğine bakar, yoksa Overpass'a gider ve
