/// Yayındaki demo sayfasına karnenin bağlantısını ekler; tek linkle ikisine de ulaşılır.
fn karne_rozeti_ekle(demo_yolu: &str, karne_adi: &str) -> Result<(), String> {
    let html = fs::read_to_string(demo_yolu).map_err(|h| format!("okunamadı: {h}"))?;
    if html.contains(karne_adi) {
        return Ok(());
    }
    let rozet = format!(
        "<a class=\"karne-rozet\" href=\"{karne_adi}\" style=\"position:fixed;right:16px;bottom:16px;z-index:9999;background:#0f172a;color:#fff;padding:10px 16px;border-radius:999px;font:500 14px/1 system-ui,sans-serif;text-decoration:none;box-shadow:0 8px 24px rgba(15,23,42,.3)\">Eksikler ve puan → dijital karne</a>"
    );
    let yeni = match html.rfind("</body>") {
        Some(i) => format!("{}{}{}", &html[..i], rozet, &html[i..]),
        None => format!("{html}{rozet}"),
    };
    fs::write(demo_yolu, yeni).map_err(|h| format!("yazılamadı: {h}"))
}
