        .unwrap_or_default()
        .trim()
        .to_string();
    let eposta = komut_calistir(kok, "git", &["config", "user.email"])
        .unwrap_or_default()
        .trim()
        .to_string();
    let ad = if ad.is_empty() {
        "Demo Yayını".to_string()
    } else {
        ad
    };
    let eposta = if eposta.is_empty() {
        "demo@localhost".to_string()
    } else {
        eposta
    };
    komut_calistir(
