      ctx.moveTo(cx + Math.cos(a) * ic, cy + Math.sin(a) * ic * 0.5);
      ctx.lineTo(cx + Math.cos(a) * dis, cy + Math.sin(a) * dis * 0.5);
      ctx.stroke();
    }

    for (var j = 0; j < YILDIZ; j++) {
      var pz = ((j / YILDIZ) + kayma * 1.25) % 1;
      var pa = (j * 2.399963) % (Math.PI * 2);
      var pr = taban * (0.04 + pz * pz);
