+    if (!m) return "255,176,87";
+    var n = parseInt(m[1], 16);
+    return ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255);
+  }
+  var vurgu = renk();
+
+  function boyutla() {
+    var dpr = Math.min(window.devicePixelRatio || 1, 2);
+    w = tuval.clientWidth || 0;
