+    if (!w || !h) return;
+    ctx.clearRect(0, 0, w, h);
+    var cx = w / 2, cy = h * 0.58, taban = Math.min(w, h);
+    var kayma = ilerleme * 1.7 + (zaman || 0) * 0.000045;
