+    if (zaman - son > 33) { ciz(zaman); son = zaman; }
+    requestAnimationFrame(dongu);
+  }
+
+  function baslat() {
+    if (!kosuyor && gorunur && !azalt.matches) requestAnimationFrame(dongu);
+  }
