<script>
(function () {
  var azalt = matchMedia("(prefers-reduced-motion: reduce)");

  /* --- Mobil menü --- */
  var ac = document.getElementById("ac");
  var menu = document.querySelector(".menu");
  if (ac && menu) {
    ac.addEventListener("click", function () {
      var gorunur = menu.style.display === "flex";
      menu.style.display = gorunur ? "" : "flex";
      menu.style.position = "absolute";
      menu.style.top = "64px";
      menu.style.left = "16px";
      menu.style.right = "16px";
      menu.style.flexDirection = "column";
      menu.style.gap = "14px";
      menu.style.padding = "18px";
      menu.style.background = "rgba(10,11,16,.97)";
      menu.style.border = "1px solid rgba(255,255,255,.1)";
      menu.style.borderRadius = "14px";
      ac.setAttribute("aria-expanded", gorunur ? "false" : "true");
    });
  }

  /* --- El feneri: imleci takip eden ışık --- */
  var fener = document.getElementById("fener");
  if (fener && matchMedia("(hover: hover) and (pointer: fine)").matches && !azalt.matches) {
    var bx = 0, by = 0, bekliyor = false;
    var yaz = function () {
      bekliyor = false;
      fener.style.setProperty("--fx", bx + "px");
      fener.style.setProperty("--fy", by + "px");
    };
    addEventListener("pointermove", function (o) {
      if (o.pointerType === "touch") return;
      bx = o.clientX; by = o.clientY;
      fener.classList.add("acik");
      if (bekliyor) return;
      bekliyor = true;
      requestAnimationFrame(yaz);
    }, { passive: true });
    document.addEventListener("pointerleave", function () { fener.classList.remove("acik"); });
  }

  /* --- Görünür olunca açılan bloklar --- */
  var ciklar = document.querySelectorAll(".cik");
  if ("IntersectionObserver" in window) {
    var goz = new IntersectionObserver(function (g) {
      g.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add("geldi"); goz.unobserve(e.target); } });
    }, { threshold: 0, rootMargin: "0px 0px -10% 0px" });
    ciklar.forEach(function (e) { goz.observe(e); });
  } else {
    ciklar.forEach(function (e) { e.classList.add("geldi"); });
  }

  /* --- Sayaçlar: görününce sayarak yükselir --- */
  function sayacBaslat() {
    document.querySelectorAll("[data-sayi]").forEach(function (el) {
      var hedef = parseFloat(el.getAttribute("data-sayi"));
      var ondalik = parseInt(el.getAttribute("data-ondalik") || "0", 10);
      if (azalt.matches) { el.textContent = hedef.toFixed(ondalik); return; }
      var basla = performance.now(), sure = 1400;
      function adim(simdi) {
        var oran = Math.min(1, (simdi - basla) / sure);
        var yumusak = 1 - Math.pow(1 - oran, 3);
        el.textContent = (hedef * yumusak).toFixed(ondalik);
        if (oran < 1) requestAnimationFrame(adim);
        else el.textContent = hedef.toFixed(ondalik);
      }
      requestAnimationFrame(adim);
    });
  }
  var sayacBolum = document.getElementById("sayaclar");
  if (sayacBolum && "IntersectionObserver" in window) {
    var sayaçGoz = new IntersectionObserver(function (g) {
      if (g[0].isIntersecting) { sayacBaslat(); sayaçGoz.disconnect(); }
    }, { threshold: 0.3 });
    sayaçGoz.observe(sayacBolum);
  } else { sayacBaslat(); }

  /* --- Kaydırmayla hareket --- */
  var heroFoto = document.getElementById("hero-foto");
  var heroIc = document.getElementById("hero-ic");
  var sahne = document.getElementById("sahne");
  var sahneFoto = document.getElementById("sahne-foto");
  var galeriResimler = [].slice.call(document.querySelectorAll(".galeri img"));
  var ust = document.getElementById("ust");
  var bekliyor = false;

  function sinirla(d, a, b) { return Math.max(a, Math.min(b, d)); }

  function konumla() {
    bekliyor = false;
    var y = scrollY, vh = innerHeight;

    if (ust) ust.classList.toggle("dolu", y > 40);

    if (heroFoto) {
      var p = sinirla(y / (vh || 1), 0, 1);
      heroFoto.style.transform = "scale(" + (1.06 + p * 0.09).toFixed(3) + ") translate3d(0," + (p * 8).toFixed(2) + "%,0)";
      if (heroIc) {
        heroIc.style.transform = "translate3d(0," + (-y * 0.16).toFixed(1) + "px,0)";
        heroIc.style.opacity = String(sinirla(1 - p * 1.15, 0, 1));
      }
    }

    if (sahne && sahneFoto) {
      var k = sahne.getBoundingClientRect();
      var toplam = k.height - vh;
      var ilerleme = toplam > 0 ? sinirla(-k.top / toplam, 0, 1) : 0;
      sahneFoto.style.transform = "scale(" + (1 + ilerleme * 0.42).toFixed(3) +
        ") translate3d(" + (ilerleme * -4).toFixed(2) + "%," + (ilerleme * -5).toFixed(2) + "%,0)";
    }

    galeriResimler.forEach(function (resim) {
      var hiz = parseFloat(resim.getAttribute("data-hiz") || "0.15");
      var kutu = resim.parentElement.getBoundingClientRect();
      var uzaklik = (kutu.top + kutu.height / 2) - vh / 2;
      var sinir = (kutu.height || 400) * 0.09;
      var kay = sinirla(-uzaklik * hiz, -sinir, sinir);
      resim.style.transform = "translate3d(0," + kay.toFixed(1) + "px,0)";
    });
  }

  function iste() {
    if (bekliyor) return;
    bekliyor = true;
    requestAnimationFrame(konumla);
  }

  if (!azalt.matches) {
    addEventListener("scroll", iste, { passive: true });
    addEventListener("resize", iste);
    iste();
  }

  /* --- Açık / kapalı --- */
  var program = {
    0: [[720, 1320]], 1: [[720, 1410]], 2: [[720, 1410]], 3: [[720, 1410]],
    4: [[720, 1410]], 5: [[720, 1410]], 6: [[720, 1320]]
  };
  var gunler = ["Pazartesi", "Salı", "Çarşamba", "Perşembe", "Cuma", "Cumartesi", "Pazar"];
  function iki(s) { return String(s).padStart(2, "0"); }
  function saat(d) { return iki(Math.floor(d / 60) % 24) + ":" + iki(d % 60); }
  function kalan(d) {
    var g = Math.floor(d / 1440), s = Math.floor((d % 1440) / 60), k = d % 60, p = [];
    if (g > 0) p.push(g + " gün");
    if (s > 0) p.push(s + " sa");
    if (k > 0) p.push(k + " dk");
    return p.length ? p.join(" ") : "0 dk";
  }
  function durum() {
    var hedef = document.getElementById("acik");
    if (!hedef) return;
    var simdi = new Date();
    var gun = (simdi.getDay() + 6) % 7;
    var dk = simdi.getHours() * 60 + simdi.getMinutes();
    var bugun = program[gun] || [];
    for (var i = 0; i < bugun.length; i++) {
      if (dk >= bugun[i][0] && dk < bugun[i][1]) {
        var sol = bugun[i][1] - dk;
        hedef.textContent = (sol <= 15 ? "🟠 Kapanmak üzere · " : "🟢 Şu an açık · ") +
          "kapanış " + saat(bugun[i][1]) + " (" + kalan(sol) + " kaldı)";
        hedef.style.color = sol <= 15 ? "#fb923c" : "#4ade80";
        return;
      }
    }
    for (var j = 0; j < 7; j++) {
      var gd = (gun + j) % 7, dilimler = program[gd] || [];
      for (var k2 = 0; k2 < dilimler.length; k2++) {
        var bas = dilimler[k2][0];
        if (j === 0 && bas <= dk) continue;
        var et = j === 0 ? "bugün" : (j === 1 ? "yarın" : gunler[gd]);
        hedef.textContent = "🔴 Şu an kapalı · açılış " + et + " " + saat(bas) + " · " +
          kalan(j * 1440 + bas - dk) + " kaldı";
        hedef.style.color = "#f87171";
        return;
      }
    }
  }
  durum();
  setInterval(durum, 60000);
})();
</script>
