/// Demo dosyasındaki kök renk değişkenini okur (`--accent:#xxxxxx`).
fn css_renk_degiskeni(html: &str, ad: &str) -> Option<String> {
    let anahtar = format!("--{ad}:");
    let bas = html.find(&anahtar)? + anahtar.len();
    let kalan = &html[bas..];
    let son = kalan.find(|k: char| k == ';' || k == '}' || k == '"')?;
    let deger = kalan[..son].trim().to_string();
    deger.starts_with('#').then_some(deger)
}

/// Üretilmiş bir demonun renklerini değiştirir. Kök değişken yoksa `None`.
fn demo_renklerini_degistir(html: &str, zemin: &str, yazi: &str, vurgu: Option<&str>) -> Option<String> {
    let eski_vurgu = css_renk_degiskeni(html, "accent")?;
    let vurgu = vurgu.filter(|v| v.starts_with('#')).unwrap_or(&eski_vurgu).to_string();
    let karsi = if parlak_mi(&vurgu) { "#12100e" } else { "#f8f5f0" };
    let kok = format!(":root{{--accent:{vurgu};--accent-karsi:{karsi};--bg:{zemin};--ink:{yazi};");
    let bas = html.find(":root{--accent:")?;
    let kalan = &html[bas..];
    let ink = kalan.find("--ink:")? + "--ink:".len();
    let son = kalan[ink..].find(|k: char| k == ';' || k == '}')? ;
    let bitis = bas + ink + son;
    let mut yeni = String::with_capacity(html.len());
    yeni.push_str(&html[..bas]);
    yeni.push_str(&kok);
    yeni.push_str(&html[bitis..]);
    // html sınıfı: açık/koyu tema
    let sinifli = if parlak_mi(zemin) {
        "<html lang=\"tr\" class=\"tema-acik\">"
    } else {
        "<html lang=\"tr\">"
    };
    let temiz = yeni
        .replace("<html lang=\"tr\" class=\"tema-acik\">", sinifli)
        .replace("<html lang=\"tr\">", sinifli)  // careful: after first replace the string already has class; the second replace would match `<html lang="tr">` only if present
    ...
}
```
