/// Eşleşme ad üzerinden yapılır (iki kaynağın bağlantısı farklıdır).
/// Tamamlanan numaranın yanında boş alanlar da doldurulur: çalışma saatleri,
/// yıldız ve inceleme sayısı; karnede ve demo sayfasında işe yarar.
/// Dönüş: (numarası tamamlanan kayıt, hâlâ numarası olmayan kayıt).
fn telefonlari_tamamla(liste: &mut [BusinessLead], google: &[BusinessLead]) -> (usize, usize) {
    let mut numarali: HashMap<String, &BusinessLead> = HashMap::new();
    for lead in google {
        if telefon_gecerli(&lead.phone) {
            numarali
                .entry(isletme_adi_anahtari(lead))
                .or_insert(lead);
        }
    }

    let mut tamamlanan = 0usize;
    for lead in liste.iter_mut() {
        if telefon_gecerli(&lead.phone) {
            continue;
        }
        let Some(eslesen) = numarali.get(&isletme_adi_anahtari(lead)) else {
            continue;
        };
        lead.phone = eslesen.phone.clone();
        if lead.calisma_saatleri.trim().is_empty() {
            lead.calisma_saatleri = eslesen.calisma_saatleri.clone();
        }
        if lead.yildiz_puani.is_none() {
            lead.yildiz_puani = eslesen.yildiz_puani;
        }
        if lead.inceleme_sayisi.is_none() {
            lead.inceleme_sayisi = eslesen.inceleme_sayisi;
        }
        tamamlanan += 1;
    }

    let eksik = liste
        .iter()
        .filter(|lead| !telefon_gecerli(&lead.phone))
        .count();
    (tamamlanan, eksik)
}

