/// adayı sayılmaz.
fn takviye_gerekli(liste: &[BusinessLead]) -> bool {
    liste.len() < GOOGLE_TAKVIYE_ESIGI
        || liste.iter().any(|lead| !telefon_gecerli(&lead.phone))
}

