/// Kota sayacını verilen gün/ay için yorumlar. Gün ya da ay değiştiyse sayaç
/// sıfırdan başlar: Google kotası aylık yenilenir.
fn kota_ozeti(kota: &GoogleKota, limitler: (usize, usize), bugun: &str, bu_ay: &str, anahtar_var: bool) -> KotaDurumu {
    let (gunluk_limit, aylik_limit) = limitler;
    let gunluk = if kota.gun == bugun { kota.gunluk } else { 0 };
    let aylik = if kota.ay == bu_ay { kota.aylik } else { 0 };
    KotaDurumu {
        gunluk_limit,
        gunluk_kalan: gunluk_limit.saturating_sub(gunluk),
        aylik_limit,
        aylik_kalan: aylik_limit.saturating_sub(aylik),
        son_kullanim: tarih_goster(&kota.gun),
        anahtar_var,
    }
}

/// "2026-11-02" → "02.11.2026"; bozuk/boş tarih gösterilmez.
fn tarih_goster(anahtar: &str) -> Option<String> {
    let parcalar: Vec<&str> = anahtar.split('-').collect();
    if parcalar.len() != 3 { return None; }
    let (yil, ay, gun) = (parcalar[0], parcalar[1], parcalar[2]);
    if yil.len() != 4 || ay.len() != 2 || gun.len() != 2 { return None; }
    Some(format!("{gun}.{ay}.{yil}"))
}

fn kota_durumu() -> KotaDurumu {
    let ayar = GoogleAyar::oku();
    let kota = kota_oku();
    kota_ozeti(&kota, (ayar.gunluk_limit, ayar.aylik_limit), &bugun_anahtari(), &ay_anahtari(), ayar.acik())
}
