/// Başlıktaki kota pili: kalan hak, bitmeye yakınsa renk değişir. Detay
/// (kullanılan/toplam, son kullanım) hover'da görünür.
fn kota_pili(ui: &mut egui::Ui, durum: &KotaDurumu, kaynak: Kaynak) -> egui::Response {
    let (metin, renk) = match (kaynak, durum.anahtar_var) {
        (Kaynak::Osm, _) => ("Google kapalı · OSM".to_string(), DIM),
        (_, false) => ("Google anahtarı yok".to_string(), DIM),
        _ => {
            let renk = if durum.gunluk_kalan == 0 || durum.aylik_kalan == 0 {
                KIRMIZI
            } else if durum.gunluk_kalan <= 2 || durum.aylik_kalan <= 20 {
                TURUNCU
            } else {
                SOLUK
            };
            (
                format!(
                    "Google bugün {}/{} · ay {}/{}",
                    durum.gunluk_kalan, durum.gunluk_limit, durum.aylik_kalan, durum.aylik_limit
                ),
                renk,
            )
        }
    };
    let boy = egui::vec2(metin_genisligi(ui, &metin, 10.5) + 24.0, 26.0);
    let (rect, cevap) = ui.allocate_exact_size(boy, egui::Sense::hover());
    let p = ui.painter();
    p.rect_filled(rect, egui::Rounding::same(99.0), KART);
    p.rect_stroke(rect, egui::Rounding::same(99.0), egui::Stroke::new(1.0_f32, KENAR));
    p.text(rect.center(), egui::Align2::CENTER_CENTER, &metin, govde_font(10.5), renk);
    let ipucu = if durum.anahtar_var {
        format!(
            "Kalan Google hakkı: bugün {}/{}, bu ay {}/{}.{}",
            durum.gunluk_kalan, durum.gunluk_limit, durum.aylik_kalan, durum.aylik_limit,
            durum.son_kullanim.as_ref().map(|t| format!(" Son kullanım {t}.")).unwrap_or_default()
        )
    } else {
        "Google Places anahtarı .env dosyasında tanımlı değil.".to_string()
    };
    cevap.on_hover_text(ipucu)
}
