+/// Arayüzdeki kota göstergesi: kalan haklar ve son kullanım tarihi.
+#[derive(Clone, Default)]
+struct KotaDurumu {
+    gunluk_limit: usize,
+    gunluk_kalan: usize,
+    aylik_limit: usize,
+    aylik_kalan: usize,
+    /// Kotanın en son kullanıldığı gün ("GG.AA.YYYY"); hiç yoksa gösterilmez.
+    son_kullanim: Option<String>,
+    /// API anahtarı tanımlı mı; değilse gösterge "Google kapalı" der.
+    anahtar_var: bool,
+}
+
+/// "2026-11-02" → "02.11.2026"; boş/bozuk tarih gösterilmez.
+fn tarih_goster(anahtar: &str) -> Option<String> {
+    let parcalar: Vec<&str> = anahtar.trim().split('-').collect();
+    if parcalar.len() != 3 {
+        return None;
+    }
+    let (yil, ay, gun) = (parcalar[0], parcalar[1], parcalar[2]);
+    if yil.len() != 4 || ay.len() != 2 || gun.len() != 2 {
+        return None;
+    }
+    if [yil, ay, gun]
+        .iter()
+        .any(|parca| !parca.chars().all(|karakter| karakter.is_ascii_digit()))
+    {
+        return None;
+    }
+    Some(format!("{gun}.{ay}.{yil}"))
+}
+
+/// Sayaçı verilen gün/ay için yorumlar: gün ya da ay değiştiyse o pencere
+/// sıfırdan başlar (Google kotası aylık yenilenir).
+fn kota_ozeti(
+    kota: &GoogleKota,
+    limitler: (usize, usize),
+    bugun: &str,
+    bu_ay: &str,
+    anahtar_var: bool,
+) -> KotaDurumu {
+    let (gunluk_limit, aylik_limit) = limitler;
+    let gunluk = if kota.gun == bugun { kota.gunluk } else { 0 };
+    let aylik = if kota.ay == bu_ay { kota.aylik } else { 0 };
+    KotaDurumu {
+        gunluk_limit,
+        gunluk_kalan: gunluk_limit.saturating_sub(gunluk),
+        aylik_limit,
+        aylik_kalan: aylik_limit.saturating_sub(aylik),
+        son_kullanim: tarih_goster(&kota.gun),
+        anahtar_var,
+    }
+}
+
+/// Diskten güncel kota durumu (ayarlar ve sayaç dosyası birlikte okunur).
+fn kota_durumu() -> KotaDurumu {
+    let ayar = GoogleAyar::oku();
+    let kota = kota_oku();
+    kota_ozeti(
+        &kota,
+        (ayar.gunluk_limit, ayar.aylik_limit),
+        &bugun_anahtari(),
+        &ay_anahtari(),
+        ayar.acik(),
+    )
+}
+
+/// Başlıktaki kota pili: kalan günlük/aylık hak. Hak bitmişse kırmızı,
+/// son 2 güne / son 20 aya inince turuncu. Ayrıntı hover'da görünür.
+fn kota_pili(ui: &mut egui::Ui, durum: &KotaDurumu, kaynak: Kaynak) -> egui::Response {
+    let (metin, renk) = if kaynak == Kaynak::Osm {
+        ("Google kapalı · OSM".to_string(), DIM)
+    } else if !durum.anahtar_var {
+        ("Google anahtarı yok".to_string(), DIM)
+    } else {
+        let renk = if durum.gunluk_kalan == 0 || durum.aylik_kalan == 0 {
+            KIRMIZI
+        } else if durum.gunluk_kalan <= 2 || durum.aylik_kalan <= 20 {
+            TURUNCU
+        } else {
+            SOLUK
+        };
+        (
+            format!(
+                "Google kalan: bugün {}/{} · ay {}/{}",
+                durum.gunluk_kalan, durum.gunluk_limit, durum.aylik_kalan, durum.aylik_limit
+            ),
+            renk,
+        )
+    };
+
+    let boy = egui::vec2(metin_genisligi(ui, &metin, 10.5) + 24.0, 26.0);
+    let (rect, cevap) = ui.allocate_exact_size(boy, egui::Sense::hover());
+    let p = ui.painter();
+    p.rect_filled(rect, egui::Rounding::same(99.0), KART);
+    p.rect_stroke(
+        rect,
+        egui::Rounding::same(99.0),
+        egui::Stroke::new(1.0_f32, KENAR),
+    );
+    p.text(
+        rect.center(),
+        egui::Align2::CENTER_CENTER,
+        &metin,
+        govde_font(10.5),
+        renk,
+    );
+
+    let ipucu = if durum.anahtar_var && kaynak != Kaynak::Osm {
+        format!(
+            "Kalan Google Places hakkı: bugün {}/{}, bu ay {}/{}.{}",
+            durum.gunluk_kalan,
+            durum.gunluk_limit,
+            durum.aylik_kalan,
+            durum.aylik_limit,
+            durum
+                .son_kullanim
+                .as_ref()
+                .map(|tarih| format!(" Son kullanım {tarih}."))
+                .unwrap_or_default()
+        )
+    } else {
+        "Google Places anahtarı .env içinde tanımlı değil; kaynak OSM kalır.".to_string()
+    };
+    cevap.on_hover_text(ipucu)
+}
