/// Manşet satırını kelime kelime maskeye alır: her kelime kendi gecikmesiyle
/// yukarı kayar (video referansındaki kademeli açılım).
fn manset_satiri(metin: &str, baslangic: usize) -> (String, usize) {
    let mut sayac = baslangic;
    let kelimeler: String = metin
        .split_whitespace()
        .map(|kelime| {
            let gecikme = sayac;
            sayac += 1;
            format!(
                "<span class=\"kelime\" style=\"--k:{gecikme}\"><i>{}</i></span>",
                kacis(kelime)
            )
        })
        .collect::<Vec<_>>()
        .join(" ");
    (format!("<span class=\"satir\">{kelimeler}</span>"), sayac)
}
```
